"""Author scalable teaching illustrations with explicit geometry and accessible descriptions."""
from pathlib import Path
from html import escape as esc
import json
root=Path(__file__).resolve().parent.parent
out=root/'assets/diagrams';out.mkdir(exist_ok=True)
ink='#183d31';green='#295849';pale='#e8f1e9';purple='#6552a0'
def text(x,y,lines,size=22,anchor='start',fill=ink):
 if isinstance(lines,str):lines=[lines]
 return '<text x="%s" y="%s" font-size="%s" text-anchor="%s" fill="%s">'%(x,y,size,anchor,fill)+''.join('<tspan x="%s" dy="%s">%s</tspan>'%(x,0 if i==0 else size*1.4,esc(line)) for i,line in enumerate(lines))+'</text>'
def rect(x,y,w,h,fill=pale,stroke=green,r=12):return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{r}" fill="{fill}" stroke="{stroke}" stroke-width="2"/>'
def card(x,y,w,h,title,lines=(),fill=pale):return rect(x,y,w,h,fill)+text(x+18,y+35,title,23)+text(x+18,y+73,lines,19)
def arrow(path,label='',x=0,y=0):return f'<path d="{path}" fill="none" stroke="{green}" stroke-width="3" marker-end="url(#arrow)"/>'+ (text(x,y,label,18,'middle') if label else '')
def svg(name,title,desc,body):
 content=f'''<svg xmlns="http://www.w3.org/2000/svg" width="900" height="540" viewBox="0 0 900 540" role="img" aria-labelledby="title desc"><title id="title">{esc(title)}</title><desc id="desc">{esc(desc)}</desc><defs><marker id="arrow" markerWidth="10" markerHeight="10" refX="9" refY="5" orient="auto"><path d="M0 0L10 5L0 10Z" fill="{green}"/></marker></defs><rect width="900" height="540" rx="16" fill="#fcfdf9"/><g font-family="Arial, sans-serif">{text(35,48,title,28)}{body}</g></svg>'''
 if name=='star-and-server-roles':content=content.replace(' marker-end="url(#arrow)"','')
 (out/(name+'.svg')).write_text(content,encoding='utf-8')
 return {'file':name+'.svg','title':title,'description':desc,'width':900,'height':540}
items={}
items['u1-hardware']=svg('ram-and-saved-files','Working memory and saved files','A saved project is read from an SSD into RAM when opened. Edits happen in the active project. Saving writes changes back to storage. Unsaved changes are not a saved copy. This simplifies application behaviour.',
 rect(55,145,275,235,'#f3f6ee')+rect(90,175,205,110,'white')+text(192,220,['SSD','Saved project'],24,'middle')+text(192,325,'Keeps saved data',20,'middle')+rect(570,145,275,235)+rect(615,183,185,95,'#d8e8dc')+text(707,218,['RAM','Active project'],24,'middle')+''.join(rect(x,168,14,15,green,green,0)+rect(x,278,14,15,green,green,0) for x in range(620,790,28))+text(707,325,'Working memory',20,'middle')+arrow('M340 205H555','OPEN',447,180)+arrow('M560 300H345','SAVE',447,345)+text(450,455,['Unsaved changes may be lost if power fails.','Autosave and recovery depend on the application.'],21,'middle'))
