for col,label in enumerate(['Row','A: Code','B: Asset','C: Quantity']):b+=text(xs[col]+12,150,label,18)
for y,row in zip([214,284,354],[['2','P01','Poster','12'],['3','A02','Audio','8'],['4','V03','Video','30']]):
 for x,label in zip(xs[:-1],row):b+=text(x+14,y,label,23)
b+=arrow('M235 265H640','stay on the matching row',445,255)+text(70,430,'=VLOOKUP("A02", A2:C4, 3, FALSE)',24)+text(70,478,'Find A02 in column A. Return column 3 of the range: 8.',21)
